# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">CLASSROOM RULES AND INSTRUCTIONS</text>\n  <rect x="35" y="60" width="190" height="175" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="130" y="88" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Polite Requests</text>\n  <text x="130" y="115" text-anchor="middle" font-size="11.5" fill="#334155">• May I come in?</text>\n  <text x="130" y="140" text-anchor="middle" font-size="11.5" fill="#334155">• Can I open the door?</text>\n  <text x="130" y="165" text-anchor="middle" font-size="11.5" fill="#334155">• May I clean the board?</text>\n  <text x="130" y="195" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">Yes, you may. / Sure.</text>\n  <rect x="255" y="60" width="190" height="175" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="88" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Imperatives (Commands)</text>\n  <text x="350" y="115" text-anchor="middle" font-size="11.5" fill="#334155">• Listen carefully!</text>\n  <text x="350" y="140" text-anchor="middle" font-size="11.5" fill="#334155">• Raise your hand!</text>\n  <text x="350" y="165" text-anchor="middle" font-size="11.5" fill="#334155">• Keep quiet!</text>\n  <text x="350" y="195" text-anchor="middle" font-size="11" font-weight="bold" fill="#16a34a">Line up, please!</text>\n  <rect x="475" y="60" width="190" height="175" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="570" y="88" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Prohibitions (Mustn\'t)</text>\n  <text x="570" y="115" text-anchor="middle" font-size="11.5" fill="#334155">• Don\'t run in the hall!</text>\n  <text x="570" y="140" text-anchor="middle" font-size="11.5" fill="#334155">• Don\'t eat in class!</text>\n  <text x="570" y="165" text-anchor="middle" font-size="11.5" fill="#334155">• You mustn\'t shout!</text>\n  <text x="570" y="195" text-anchor="middle" font-size="11" font-weight="bold" fill="#db2777">Follow the rules!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SCHOOL SUBJECTS AND TIMETABLE</text>\n  <rect x="25" y="55" width="200" height="180" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="125" y="82" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Core Subjects</text>\n  <text x="40" y="110" font-size="12" fill="#334155">• Maths (Mathematics)</text>\n  <text x="40" y="135" font-size="12" fill="#334155">• Science (Fen Bilimleri)</text>\n  <text x="40" y="160" font-size="12" fill="#334155">• Social Studies</text>\n  <text x="40" y="185" font-size="12" fill="#334155">• Turkish / English</text>\n  <text x="125" y="215" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">What\'s your favourite?</text>\n  <rect x="250" y="55" width="200" height="180" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="350" y="82" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Creative &amp; Physical</text>\n  <text x="265" y="110" font-size="12" fill="#713f12">• Art (Görsel Sanatlar)</text>\n  <text x="265" y="135" font-size="12" fill="#713f12">• Music (Müzik)</text>\n  <text x="265" y="160" font-size="12" fill="#713f12">• P.E. (Physical Education)</text>\n  <text x="265" y="185" font-size="12" fill="#713f12">• I.T. (Information Tech.)</text>\n  <text x="350" y="215" text-anchor="middle" font-size="11" font-weight="bold" fill="#ca8a04">I like doing sports.</text>\n  <rect x="475" y="55" width="200" height="180" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="575" y="82" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Days &amp; Prepositions</text>\n  <text x="490" y="110" font-size="12" fill="#14532d">• Monday, Tuesday</text>\n  <text x="490" y="135" font-size="12" fill="#14532d">• Wednesday, Thursday</text>\n  <text x="490" y="160" font-size="12" fill="#14532d">• Friday, Saturday, Sunday</text>\n  <text x="575" y="190" text-anchor="middle" font-size="12" font-weight="bold" fill="#16a34a">Rule: ON Monday</text>\n  <text x="575" y="215" text-anchor="middle" font-size="11" fill="#475569">Günlerden önce \'on\' gelir</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">EXPRESSING LIKES, DISLIKES &amp; TIMETABLES</text>\n  <rect x="40" y="60" width="300" height="175" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="190" y="85" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Likes and Dislikes</text>\n  <text x="60" y="115" font-size="12" fill="#334155">• I like solving problems in Maths.</text>\n  <text x="60" y="145" font-size="12" fill="#334155">• She loves doing experiments in Science.</text>\n  <text x="60" y="175" font-size="12" fill="#334155">• I dislike drawing pictures in Art.</text>\n  <text x="60" y="205" font-size="12" font-weight="bold" fill="#2563eb">• What is your favourite subject?</text>\n  <rect x="360" y="60" width="300" height="175" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="510" y="85" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Timetable Dialogue</text>\n  <text x="380" y="115" font-size="12" fill="#334155">A: When do we have English?</text>\n  <text x="380" y="140" font-size="12" fill="#16a34a">B: We have English on Tuesday and Friday.</text>\n  <text x="380" y="170" font-size="12" fill="#334155">A: Do you have P.E. on Wednesday?</text>\n  <text x="380" y="195" font-size="12" fill="#16a34a">B: Yes, we do. I love playing basketball.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
